// Lê o evento da uazapi e decide se ele entra no fluxo de feedback.
// Entra só mensagem de TEXTO ou ÁUDIO, de cliente, em conversa individual.
// Devolve UM item com o que importa, ou nenhum item (o fluxo para aqui).
const body = $input.first().json.body || {};
const m = body.message || {};
const parar = [];

if (body.EventType !== 'messages') return parar;
// Grupo e mensagem do próprio número (o dono no celular ou a resposta automática).
if (m.isGroup === true || m.fromMe === true) return parar;
// Edição de uma mensagem já enviada não é mensagem nova.
if (typeof m.edited === 'string' && m.edited.trim() !== '') return parar;

const token = String(body.token || '').trim();
const baseUrl = String(body.BaseUrl || '').trim().replace(/\/+$/, '');
const messageId = String(m.messageid || '').trim();
if (!token || !/^https:\/\//i.test(baseUrl) || !messageId) return parar;

// Telefone do cliente: a conversa individual (...@s.whatsapp.net). Na conversa
// no formato novo do WhatsApp (...@lid), o telefone real vem em sender_pn.
const jid = [m.chatid, m.sender_pn]
  .map((v) => String(v || ''))
  .find((v) => v.endsWith('@s.whatsapp.net'));
if (!jid) return parar;
const telefone = jid.split('@')[0].replace(/\D/g, '');
if (telefone.length < 10 || telefone.length > 15) return parar;

// Só texto e áudio. Foto, vídeo, figurinha, reação, documento etc. não entram.
let tipo = null;
let texto = '';
if (m.messageType === 'AudioMessage') {
  tipo = 'audio';
} else if (m.messageType === 'Conversation' || m.messageType === 'ExtendedTextMessage') {
  tipo = 'texto';
  texto = (typeof m.text === 'string' ? m.text : '').trim();
  if (!texto) return parar;
} else {
  return parar;
}

// Nome do perfil do WhatsApp: a Helena chama a pessoa pelo primeiro nome
// quando ele parece nome de gente. Só letras e espaços (emoji e símbolo saem).
const nome = String(m.senderName || '').replace(/[^\p{L}\s'-]/gu, ' ').replace(/\s+/g, ' ').trim().slice(0, 40);

return [{ json: { token, baseUrl, messageId, telefone, nome, tipo, texto: texto.slice(0, 4000) } }];

// A conta pode receber feedback agora? O restaurante foi achado pelo token
// da instância. Precisa: onboarding completo, assinatura ativa e conta não excluída.
const r = $input.first().json;
if (!r.id || r.excluida_em || r.onboarding_completo !== true || r.assinatura_status !== 'ativa') return [];

return [{
  json: {
    ...$('Lê a mensagem').first().json,
    restauranteId: r.id,
    nomeRestaurante: String(r.nome_restaurante || '').trim(),
    // Número de contato/suporte das Configurações (só dígitos) — nulo = não indicar.
    telefoneContato: String(r.telefone_contato || '').replace(/\D/g, '') || null,
  },
}];

// Áudio transcrito vira texto como qualquer outra mensagem. Se o download ou
// a transcrição falharam, o fluxo para em silêncio (não há o que analisar).
const t = String($input.first().json.text || '').trim();
if (!t) return [];
return [{ json: { ...$('Restaurante ativo?').first().json, texto: t.slice(0, 4000) } }];

// Junta as mensagens que a pessoa mandou em sequência.
// Cada mensagem espera 20 s; só segue quem for a ÚLTIMA da conversa naquele
// momento — se chegou outra depois, é ela que vai juntar tudo.
const meu = $('Guarda no buffer').first().json;
const linhas = $input.all().map((i) => i.json).filter((r) => r.id != null);
if (!linhas.length) return [];

linhas.sort((a, b) => Number(a.id) - Number(b.id));
const ultima = linhas[linhas.length - 1];
if (Number(ultima.id) !== Number(meu.id)) return [];

// A uazapi às vezes entrega o mesmo evento duas vezes: tira as repetidas.
const vistos = new Set();
const textos = [];
for (const r of linhas) {
  let d = r.message_data;
  if (typeof d === 'string') { try { d = JSON.parse(d); } catch (e) { d = {}; } }
  const id = d && d.messageid;
  if (id) {
    if (vistos.has(id)) continue;
    vistos.add(id);
  }
  const t = String(r.message_content || '').trim();
  if (t) textos.push(t);
}
const textoCompleto = textos.join('\n').slice(0, 6000).trim();
if (!textoCompleto) return [];

return [{ json: { ...$('Restaurante ativo?').first().json, textoCompleto, ateId: Number(ultima.id), remoteId: meu.remote_id } }];

// Valida o que a IA devolveu e decide: o que gravar e o que responder.
// Quem responde é a Helena, do atendimento do restaurante, com mensagens
// prontas sorteadas (seção 4).
// Regras:
//   - Feedback (há pelo menos um ponto)  -> grava e agradece.
//   - Pergunta/pedido COMPLETO sobre o restaurante -> indica o número de
//     contato das Configurações, só o número, sem link (sem número: só avisa
//     que o canal é de feedback). Pergunta incompleta ("tenho uma dúvida"),
//     em que não dá para saber o assunto, não é respondida.
//   - Feedback + pergunta                 -> agradece e encaminha, numa mensagem só.
//   - Qualquer outra coisa (saudação sozinha, "obrigado", assunto fora do
//     restaurante)                         -> não responde.
const base = $('Sou a última mensagem?').first().json;

const CATEGORIAS = ['Comida', 'Bebidas', 'Atendimento', 'Ambiente', 'Limpeza', 'Preço', 'Tempo de Espera',
  'Reserva', 'Estacionamento', 'Acessibilidade', 'Música/Som', 'Cardápio/Variedade', 'Higiene', 'Outros'];
const semAcento = (s) => String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();

// 1. A resposta da IA (modo JSON) vira objeto.
const bruto = String($input.first().json.text || '');
let r = null;
try {
  r = JSON.parse(bruto);
} catch (e) {
  const achado = bruto.match(/\{[\s\S]*\}/);
  if (achado) {
    try { r = JSON.parse(achado[0]); } catch (e2) { r = null; }
  }
}
if (!r || typeof r !== 'object' || Array.isArray(r)) {
  // Sem formato não dá para gravar nem responder com segurança: a execução
  // fica marcada como erro no n8n para alguém ver.
  throw new Error('A IA devolveu algo fora do formato: ' + bruto.slice(0, 300));
}

// 2. Pontos válidos: categoria da lista fixa e um dos 4 sentimentos.
//    Neutro e Sugestão são valores distintos e nunca viram um no outro.
const sentimentoDoPonto = (valor) => {
  const v = semAcento(valor);
  if (v.includes('negativ')) return 'Negativo';
  if (v.includes('sugest')) return 'Sugestão';
  if (v.includes('positiv')) return 'Positivo';
  if (v.includes('neutr')) return 'Neutro';
  return null;
};
const pontos = [];
for (const p of Array.isArray(r.pontos) ? r.pontos : []) {
  if (!p || typeof p !== 'object') continue;
  const sentimento = sentimentoDoPonto(p.sentimento);
  if (!sentimento) continue;
  const categoria = CATEGORIAS.find((c) => semAcento(c) === semAcento(p.categoria)) || 'Outros';
  const texto = String(p.feedback_original || '').trim();
  const resumo = String(p.resumo || '').trim();
  if (!texto && !resumo) continue;
  pontos.push({
    texto_original: (texto || resumo).slice(0, 1000),
    categoria,
    sentimento,
    resumo: (resumo || texto).slice(0, 120),
  });
}

// 3. Sentimento da mensagem inteira (mesma ordem da feedbacks_originais_view):
//    positivo e negativo > negativo > positivo > sugestão > neutro.
const tem = (s) => pontos.some((p) => p.sentimento === s);
let sentimentoGeral = null;
if (pontos.length) {
  if (tem('Positivo') && tem('Negativo')) sentimentoGeral = 'Positivo e Negativo';
  else if (tem('Negativo')) sentimentoGeral = 'Negativo';
  else if (tem('Positivo')) sentimentoGeral = 'Positivo';
  else if (tem('Sugestão')) sentimentoGeral = 'Sugestão';
  else sentimentoGeral = 'Neutro';
}
const ehFeedback = pontos.length > 0;
// Só encaminha pergunta completa: sem o assunto, não dá para dizer com o que
// o número de contato ajuda — e "tenho uma dúvida" sozinho fica sem resposta.
const sobre = String(r.assunto_pergunta || '').trim().replace(/[.!?;:]+$/, '');
const temPergunta = (semAcento(r.tipo) === 'pergunta_restaurante' || r.tem_pergunta_restaurante === true) && sobre !== '';

// 4. O texto da resposta: mensagens prontas, escritas do jeito que uma pessoa
//    escreve no WhatsApp, sorteadas conforme o sentimento. A Helena sempre diz
//    o nome. A IA só completa pedaços curtos ({nome}, {problema}, {elogio},
//    {ideia}); se um pedaço vier estranho, o sorteio fica só com as mensagens
//    que não usam ele.
const sortear = (lista) => lista[Math.floor(Math.random() * lista.length)];

// Pedaço vindo da IA: curto, minúsculo, começando com artigo ("a pizza fria").
const trecho = (v) => {
  const t = String(v || '').trim().replace(/[.!?;:,]+$/, '');
  if (!t || t.length > 45 || t.split(/\s+/).length > 7) return '';
  if (!/^(a|o|as|os) [a-zà-ÿ0-9]/.test(t)) return '';
  if (/[.!?;:"“”()]|https?:|\d{4,}/.test(t)) return '';
  return t;
};
// "por" + "a pizza fria" = "pela pizza fria"; "de" + "o garçom" = "do garçom".
const CONTRACOES = {
  por: { a: 'pela', o: 'pelo', as: 'pelas', os: 'pelos' },
  de: { a: 'da', o: 'do', as: 'das', os: 'dos' },
};
const contrai = (prep, t) => {
  if (!t) return '';
  const partes = t.split(' ');
  return CONTRACOES[prep][partes[0]] + ' ' + partes.slice(1).join(' ');
};
const nomeDaIA = String(r.primeiro_nome || '').trim();
const primeiroNome = /^[A-ZÀ-Ý][a-zà-ÿ]{1,14}$/.test(nomeDaIA) ? nomeDaIA : '';
const elogio = trecho(r.elogio);
const problema = trecho(r.problema);
const ideia = trecho(r.ideia);

// "do Camelo", mas "da Pizzaria Bella".
const restaurante = String(base.nomeRestaurante || '').trim();
const FEMININOS = ['pizzaria', 'cantina', 'churrascaria', 'padaria', 'lanchonete', 'casa', 'hamburgueria',
  'sorveteria', 'cafeteria', 'confeitaria', 'trattoria', 'osteria', 'esfiharia', 'pastelaria', 'tapiocaria',
  'creperia', 'doceria', 'adega', 'choperia', 'chopperia', 'cervejaria', 'peixaria', 'petiscaria', 'galeteria',
  'marmitaria', 'cozinha', 'tasca', 'taberna', 'bodega', 'panificadora', 'sanduicheria', 'temakeria',
  'pamonharia', 'brasa', 'vila', 'toca', 'esquina', 'fazenda', 'quinta', 'barraca', 'tenda', 'cabana'];
const primeiraPalavra = semAcento(restaurante.split(/\s+/)[0] || '');
const doRestaurante = restaurante
  ? (FEMININOS.includes(primeiraPalavra) ? 'da ' : 'do ') + restaurante
  : 'do restaurante';

// O número vai só com dígitos e o 55 na frente (5511987654321): sem
// parênteses, sem hífen e sem link.
const contato = base.telefoneContato ? (base.telefoneContato.length <= 11 ? '55' + base.telefoneContato : base.telefoneContato) : '';

const VARS = {
  nome: primeiroNome,
  doRestaurante,
  elogio,
  doElogio: contrai('de', elogio),
  peloProblema: contrai('por', problema),
  doProblema: contrai('de', problema),
  daIdeia: contrai('de', ideia),
  sobre,
  contato,
};
// Uma mensagem só entra no sorteio se tiver tudo o que ela usa.
const cabe = (m) => [...m.matchAll(/\{(\w+)\}/g)].every((x) => VARS[x[1]]);
const escolher = (lista) => sortear(lista.filter(cabe)).replace(/\{(\w+)\}/g, (_, k) => VARS[k]);

// Primeira conversa (o número não respondeu essa pessoa nos últimos 30 dias)
// ou já conversaram: muda o cumprimento, mas o nome da Helena vai sempre.
const apresentar = !$('Já falou com a pessoa?').first().json.id;
const SAUDACAO_PRIMEIRA = [
  'Oi, {nome}! Aqui é a Helena, {doRestaurante}.',
  'Oi, {nome}, tudo bem? Aqui é a Helena, {doRestaurante}.',
  'Olá, {nome}! Sou a Helena, {doRestaurante}.',
  'Oi! Aqui é a Helena, {doRestaurante}.',
  'Oi, tudo bem? Aqui é a Helena, {doRestaurante}.',
  'Olá! Sou a Helena, {doRestaurante}.',
  'Oi! Helena aqui, {doRestaurante}.',
];
const SAUDACAO_DE_NOVO = [
  'Oi, {nome}! Helena de novo por aqui.',
  'Oi de novo, {nome}! Aqui é a Helena.',
  'Oi, {nome}! É a Helena, {doRestaurante}.',
  'Oi de novo! Aqui é a Helena.',
  'Oi! Helena de novo por aqui.',
  'Oi! É a Helena, {doRestaurante}.',
];

const MENSAGENS = {
  positivo: [
    'Que bom que você gostou! Obrigada por mandar mensagem, volta sempre 😊',
    'Fiquei muito feliz com sua mensagem! Vou mostrar pro pessoal aqui, eles vão adorar.',
    'Ahh, que bom saber! Obrigada pelo carinho, viu? Te esperamos de novo.',
    'Obrigada por contar! Bom demais saber que deu tudo certo 😊',
    'Que alegria ler isso! Vou repassar pra equipe agora mesmo. Volta sempre!',
    'Muito obrigada! Mensagem assim faz o dia da gente aqui 😊',
    'Que bom que você gostou {doElogio}! Vou contar pro pessoal, eles vão ficar felizes.',
    'Obrigada! Vou passar o elogio {doElogio} pro pessoal, eles vão adorar saber.',
    'Que bom ler isso sobre {elogio}! Obrigada por contar, volta sempre 😊',
  ],
  negativo: [
    'Poxa, sinto muito. Não era pra ter sido assim. Obrigada por avisar, já passei pro pessoal responsável.',
    'Nossa, desculpa mesmo. Vou falar com a equipe hoje ainda pra ver o que aconteceu.',
    'Que chato, sinto muito por isso. Obrigada por contar, já deixei anotado pro pessoal.',
    'Poxa, me desculpa. Obrigada pela sinceridade, vou repassar pra equipe agora.',
    'Sinto muito mesmo. Já passei sua mensagem pro pessoal daqui, obrigada por avisar.',
    'Puxa, que pena. Desculpa pelo transtorno, vou levar isso pro pessoal responsável.',
    'Poxa, sinto muito {peloProblema}. Obrigada por avisar, já passei pro pessoal responsável.',
    'Nossa, desculpa {peloProblema}! Vou falar com a equipe pra ver o que aconteceu.',
    'Que chato isso {doProblema}, desculpa mesmo. Já repassei pro pessoal daqui.',
    'Sinto muito {peloProblema}. Obrigada por contar, vou levar isso pra equipe hoje.',
  ],
  misto: [
    'Obrigada por contar tudo! Fico feliz com o que você gostou e sinto muito pelo que não foi legal. Vou passar pro pessoal.',
    'Que bom que teve coisa boa! E desculpa pelo que deixou a desejar, já repassei pra equipe.',
    'Obrigada pela sinceridade! Anotei o que você gostou e o que precisa melhorar, vou passar tudo pro pessoal.',
    'Obrigada por avisar! Vou mostrar os elogios e as reclamações pro pessoal aqui.',
    'Que bom que você gostou {doElogio}! E desculpa {peloProblema}, já passei pro pessoal responsável.',
    'Obrigada por contar! Fico feliz com {elogio} e sinto muito {peloProblema}. Vou falar com a equipe.',
    'Obrigada pelo retorno! Que bom que teve coisa boa, e desculpa {peloProblema}. Vou levar pra equipe.',
  ],
  neutro: [
    'Obrigada por contar como foi! Vou passar pro pessoal aqui.',
    'Valeu pelo retorno! Já anotei aqui pra equipe.',
    'Obrigada pela opinião! Ajuda muito a gente a melhorar.',
    'Obrigada por mandar mensagem! Anotei aqui e vou repassar pro pessoal.',
    'Que bom que você escreveu! Vou mostrar pra equipe, obrigada.',
    'Anotado! Obrigada por compartilhar com a gente.',
  ],
  sugestao: [
    'Adorei a sugestão, obrigada! Vou passar pro pessoal aqui.',
    'Obrigada pela sugestão! Já anotei e vou levar pra equipe.',
    'Que ideia boa! Vou repassar pro pessoal, obrigada por sugerir.',
    'Anotado! Obrigada pela sugestão, vou mostrar pra equipe.',
    'Adorei a ideia {daIdeia}! Vou passar pro pessoal aqui, obrigada.',
    'Obrigada pela sugestão {daIdeia}! Já anotei pra equipe.',
    'Que ideia boa essa {daIdeia}! Vou levar pro pessoal, obrigada 😊',
  ],
};
// Sugestão que veio junto de outro sentimento: um complemento curto.
const TAMBEM_SUGESTAO = [
  'Ah, e anotei sua sugestão também!',
  'E obrigada pela ideia {daIdeia}, vou passar adiante.',
  'Sua sugestão também ficou anotada, viu?',
];
// Pergunta sobre o restaurante: o canal é só de opinião; indica o contato.
const ENCAMINHA_JUNTO = [
  'Sobre {sobre}, por aqui eu não consigo te ajudar, esse número é só pra receber a opinião dos clientes.',
  'Ah, sobre {sobre}: esse número é só pra opiniões, então por aqui eu não consigo te ajudar.',
];
const ENCAMINHA_SO = [
  'Esse número é só pra receber a opinião dos clientes sobre o restaurante, então com {sobre} eu não consigo te ajudar por aqui.',
  'Por aqui eu só recebo a opinião dos clientes sobre o restaurante, então com {sobre} não consigo te ajudar.',
];
const PELO_CONTATO = [
  'Pra isso é só chamar a gente no número {contato}.',
  'Mas é só chamar a gente no número {contato}.',
];
const CENARIO = {
  'Positivo e Negativo': 'misto',
  Negativo: 'negativo',
  Positivo: 'positivo',
  'Sugestão': 'sugestao',
  Neutro: 'neutro',
};

const saudacao = escolher(apresentar ? SAUDACAO_PRIMEIRA : SAUDACAO_DE_NOVO);
const encaminhamento = (lista) => escolher(lista) + (contato ? ' ' + escolher(PELO_CONTATO) : '');

let resposta = '';
if (ehFeedback) {
  const cenario = CENARIO[sentimentoGeral];
  resposta = saudacao + ' ' + escolher(MENSAGENS[cenario]);
  if (cenario !== 'sugestao' && tem('Sugestão')) resposta += ' ' + escolher(TAMBEM_SUGESTAO);
  if (temPergunta) resposta += '\n\n' + encaminhamento(ENCAMINHA_JUNTO);
} else if (temPergunta) {
  resposta = saudacao + ' ' + encaminhamento(ENCAMINHA_SO);
}

// "Digitando..." antes de enviar, do tempo de alguém escrever esse texto
// (entre 2,5 e 8 segundos).
const digitandoMs = resposta ? Math.min(8000, Math.max(2500, Math.round(resposta.length * 35))) : 0;

return [{
  json: {
    restauranteId: base.restauranteId,
    telefone: base.telefone,
    baseUrl: base.baseUrl,
    token: base.token,
    textoCompleto: base.textoCompleto,
    ehFeedback,
    sentimentoGeral,
    pontos,
    resposta,
    digitandoMs,
  },
}];

// Um item por ponto, já ligado à mensagem original que acabou de ser salva.
const r = $('Monta a resposta').first().json;
const origemId = $input.first().json.id;
if (!origemId) throw new Error('A mensagem original não foi salva (sem id).');
return r.pontos.map((p) => ({
  json: {
    texto_original: p.texto_original,
    categoria: p.categoria,
    sentimento: p.sentimento,
    resumo: p.resumo,
    telefone_cliente: r.telefone,
    restaurante_id: r.restauranteId,
    origem_id: origemId,
  },
}));
